public with sharing class ContactDomainService {
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> byEmailDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return byEmailDomain;
        }

        List<Id> ids = new List<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                ids.add(accountId);
            }
        }

        if (ids.isEmpty()) {
            return byEmailDomain;
        }

        final Integer chunkSize = 200;
        Integer startIndex = 0;

        while (startIndex < ids.size()) {
            Integer endIndex = startIndex + chunkSize;
            if (endIndex > ids.size()) {
                endIndex = ids.size();
            }

            Set<Id> chunk = new Set<Id>(ids.subList(startIndex, endIndex));

            for (Contact c : [SELECT Id, Email, AccountId FROM Contact WHERE AccountId IN :chunk]) {
                String email = c.Email == null ? null : c.Email.trim();
                if (String.isBlank(email)) {
                    continue;
                }

                Integer atIndex = email.lastIndexOf('@');
                if (atIndex <= 0 || atIndex == email.length() - 1) {
                    continue;
                }

                String domain = email.substring(atIndex + 1).trim().toLowerCase();
                if (String.isBlank(domain)) {
                    continue;
                }

                List<Contact> contacts = byEmailDomain.get(domain);
                if (contacts == null) {
                    contacts = new List<Contact>();
                    byEmailDomain.put(domain, contacts);
                }
                contacts.add(c);
            }

            startIndex = endIndex;
        }

        return byEmailDomain;
    }
}
