public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // --- Validate maxRows ---
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // --- Validate fields ---
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields must not be null or empty.');
        }

        // --- Validate objectApiName ---
        if (String.isBlank(objectApiName)) {
            throw new SearchException('objectApiName must not be blank.');
        }

        Map<String, Schema.SObjectType> globalMap = Schema.getGlobalDescribe();
        Schema.SObjectType sObjType = globalMap.get(objectApiName.toLowerCase());
        if (sObjType == null) {
            throw new SearchException('Object not found: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objDesc = sObjType.getDescribe();

        // --- Object-level read access ---
        if (!objDesc.isAccessible()) {
            throw new SearchException('The running user cannot read the object: ' + objectApiName);
        }

        Map<String, Schema.SObjectField> fieldMap = objDesc.fields.getMap();

        // --- Resolve and validate SELECT fields ---
        List<String> selectFields = new List<String>{ 'Id' };
        Set<String> addedLower = new Set<String>{ 'id' };
        for (String f : fields) {
            if (String.isBlank(f)) {
                throw new SearchException('A field name in fields is blank.');
            }
            String lower = f.toLowerCase();
            if (addedLower.contains(lower)) {
                continue; // avoid duplicate Id
            }
            Schema.SObjectField sf = fieldMap.get(lower);
            if (sf == null) {
                throw new SearchException('Field not found on object: ' + f);
            }
            Schema.DescribeFieldResult fd = sf.getDescribe();
            if (!fd.isAccessible()) {
                throw new SearchException('The running user cannot read field: ' + f);
            }
            addedLower.add(lower);
            selectFields.add(fd.getName());
        }

        // --- Build WHERE clause ---
        List<String> whereParts = new List<String>();
        if (filters != null && !filters.isEmpty()) {
            for (Map.Entry<String, Object> entry : filters.entrySet()) {
                String key = entry.getKey();
                if (String.isBlank(key)) {
                    throw new SearchException('A filter key is blank.');
                }
                Schema.SObjectField sf = fieldMap.get(key.toLowerCase());
                if (sf == null) {
                    throw new SearchException('Filter field not found on object: ' + key);
                }
                Schema.DescribeFieldResult fd = sf.getDescribe();
                if (!fd.isAccessible()) {
                    throw new SearchException('The running user cannot read field: ' + key);
                }
                if (!fd.isFilterable()) {
                    throw new SearchException('Field is not filterable: ' + key);
                }
                whereParts.add(fd.getName() + ' = ' + escapeValue(entry.getValue()));
            }
        }

        // --- Build ORDER BY clause ---
        String orderByClause = '';
        if (String.isNotBlank(orderByField)) {
            Schema.SObjectField sf = fieldMap.get(orderByField.toLowerCase());
            if (sf == null) {
                throw new SearchException('Order-by field not found on object: ' + orderByField);
            }
            Schema.DescribeFieldResult fd = sf.getDescribe();
            if (!fd.isAccessible()) {
                throw new SearchException('The running user cannot read field: ' + orderByField);
            }
            Schema.FieldType ft = fd.getType();
            if (ft == Schema.FieldType.ADDRESS
                || ft == Schema.FieldType.LOCATION
                || ft == Schema.FieldType.COMPLEXVALUE) {
                throw new SearchException('Field cannot be used in ORDER BY: ' + orderByField);
            }
            orderByClause = ' ORDER BY ' + fd.getName() + ' ASC';
        }

        // --- Assemble and execute SOQL ---
        String soql =
            'SELECT ' + String.join(selectFields, ', ') +
            ' FROM ' + objDesc.getName() +
            (whereParts.isEmpty() ? '' : ' WHERE ' + String.join(whereParts, ' AND ')) +
            orderByClause +
            ' LIMIT ' + maxRows;

        List<SObject> results;
        try {
            results = Database.query(soql);
        } catch (Exception e) {
            throw new SearchException('Query execution failed: ' + e.getMessage());
        }
        return results;
    }

    /**
     * Converts a filter value to a safe SOQL literal, preventing injection.
     */
    private static String escapeValue(Object value) {
        if (value == null) {
            return 'NULL';
        }
        // Id must be checked before String (though Id is not a subclass of String in Apex,
        // checking first is defensive in case of implicit conversions).
        if (value instanceof Id) {
            return '\'' + String.escapeSingleQuotes((String) value) + '\'';
        }
        if (value instanceof String) {
            return '\'' + String.escapeSingleQuotes((String) value) + '\'';
        }
        if (value instanceof Boolean) {
            return (Boolean) value ? 'TRUE' : 'FALSE';
        }
        if (value instanceof Date) {
            return 'DATE ' + ((Date) value).format('yyyy-MM-dd');
        }
        if (value instanceof Datetime) {
            return String.valueOf(((Datetime) value).formatGmt('yyyy-MM-dd\'T\'HH:mm:ss\'Z\''));
        }
        if (value instanceof Decimal) {
            return String.valueOf((Decimal) value);
        }
        if (value instanceof Integer) {
            return String.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return String.valueOf((Long) value);
        }
        if (value instanceof Double) {
            return String.valueOf((Double) value);
        }
        if (value instanceof SObject) {
            throw new SearchException('SObject values are not supported as filter values.');
        }
        // Fallback: escape as string
        return '\'' + String.escapeSingleQuotes(String.valueOf(value)) + '\'';
    }
}
