public with sharing class ContactLookupAction {

    @InvocableMethod(
        label='Find Contact by Email'
        description='Looks up a Contact by email address (case-insensitive, trimmed input). Returns the earliest-created match if duplicates exist.'
    )
    public static List<Result> find(List<Request> requests) {

        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // Prepare trimmed emails parallel to input and collect unique non-blank values
        Set<String> uniqueEmails = new Set<String>();
        List<String> trimmedInput = new List<String>();

        for (Request req : requests) {
            String email = (req != null && req.email != null) ? req.email.trim() : null;
            trimmedInput.add(email);
            if (String.isNotBlank(email)) {
                uniqueEmails.add(email);
            }
        }

        // Single SOQL query – respects running-user sharing (class is `with sharing`)
        Map<String, Contact> emailToContact = new Map<String, Contact>();
        if (!uniqueEmails.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :uniqueEmails
                ORDER BY CreatedDate ASC
            ]) {
                // Keep only the first (earliest) contact per normalised email
                String key = c.Email.toLowerCase();
                if (!emailToContact.containsKey(key)) {
                    emailToContact.put(key, c);
                }
            }
        }

        // Build one Result per Request, in order
        for (Integer i = 0; i < trimmedInput.size(); i++) {
            Result res = new Result();
            String email = trimmedInput[i];

            if (String.isNotBlank(email)) {
                Contact match = emailToContact.get(email.toLowerCase());
                res.contactId = (match != null) ? match.Id : null;
                res.found     = (match != null);
            } else {
                res.contactId = null;
                res.found     = false;
            }

            results.add(res);
        }

        return results;
    }

    // ── Input ──────────────────────────────────────────────────────────────
    public class Request {
        @InvocableVariable(required=true label='Email')
        public String email;
    }

    // ── Output ─────────────────────────────────────────────────────────────
    public class Result {
        @InvocableVariable(label='Contact Id')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;
    }
}
