public with sharing class LogPurgeJob implements Schedulable {

    private static final Integer BATCH_SIZE = 10000;

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext sc) {
        DateTime thirtyDaysAgo = Datetime.now().addDays(-30);
        DateTime oneHundredEightyDaysAgo = Datetime.now().addDays(-180);

        // Non-ERROR logs older than 30 days
        List<FB_Integration_Log__c> logsToPurge = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :thirtyDaysAgo
              AND (Level__c != 'ERROR' OR Level__c = NULL)
        ];

        // ERROR logs older than 180 days
        List<FB_Integration_Log__c> errorLogsToPurge = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :oneHundredEightyDaysAgo
              AND Level__c = 'ERROR'
        ];

        logsToPurge.addAll(errorLogsToPurge);

        // Delete in batches to stay within governor limits
        for (Integer i = 0; i < logsToPurge.size(); i += BATCH_SIZE) {
            Integer end = Math.min(i + BATCH_SIZE, logsToPurge.size());
            Database.delete(logsToPurge.get(i, i + BATCH_SIZE), false);
        }
    }

    public static Id scheduleNightly() {
        String cronExpression = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
}
