public class Opportunities extends fflib_SObjectDomain {
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public Opportunities(List<SObject> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }

    public override void afterInsert() {
        super.afterInsert();

        if (records == null || records.isEmpty()) {
            return;
        }

        Set<Id> qualifyingIds = new Set<Id>();

        for (SObject record : records) {
            Opportunity opportunity = (Opportunity) record;

            if (opportunity.Id != null && opportunity.StageName == STAGE_CLOSED_WON) {
                qualifyingIds.add(opportunity.Id);
            }
        }

        startFulfilment(qualifyingIds);
    }

    public override void afterUpdate() {
        super.afterUpdate();

        if (records == null || records.isEmpty()) {
            return;
        }

        Map<Id, SObject> oldRecords = (oldMap != null) ? oldMap : Trigger.oldMap;

        if (oldRecords == null) {
            return;
        }

        Set<Id> qualifyingIds = new Set<Id>();

        for (SObject record : records) {
            Opportunity opportunity = (Opportunity) record;
            Opportunity oldOpportunity = (Opportunity) oldRecords.get(opportunity.Id);

            if (
                opportunity.Id != null &&
                oldOpportunity != null &&
                opportunity.StageName == STAGE_CLOSED_WON &&
                oldOpportunity.StageName != STAGE_CLOSED_WON
            ) {
                qualifyingIds.add(opportunity.Id);
            }
        }

        startFulfilment(qualifyingIds);
    }

    private void startFulfilment(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return;
        }

        IOpportunityFulfilmentService fulfilmentService =
            (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);

        fulfilmentService.startFulfilment(opportunityIds);
    }
}
