    }

    public override void beforeInsert(List<SObject> records) {
        for (Opportunity opp : (List<Opportunity>) records) {
            if (opp.Amount < 0) {
                error('Amount cannot be negative.', opp, 'Amount');
            }
        }
    }

    public override void beforeUpdate(List<SObject> newRecords, Map<Id, SObject> oldRecords) {
        for (Opportunity opp : (List<Opportunity>) newRecords) {
            if (opp.Amount < 0) {
                error('Amount cannot be negative.', opp, 'Amount');
            }
            Opportunity oldOpp = (Opportunity) oldRecords.get(opp.Id);
            if (oldOpp.StageName == 'Closed Won' && opp.Amount != oldOpp.Amount) {
                error('Amount cannot change on a won opportunity.', opp, 'Amount');
            }
        }
    }
}
