public with sharing class AccountOnboardingService {

    /**
     * Creates one Account per map entry and Contacts for each last name listed,
     * all orchestrated through a single Unit of Work commit.
     *
     * @param contactLastNamesByAccountName  key = Account Name, value = list of Contact LastNames
     * @return the newly inserted Accounts with populated Ids
     */
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        List<Account> newAccounts = new List<Account>();

        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return newAccounts;
        }

        // Single UoW that knows the object types involved (Order matters: parents first)
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new SObject_TypeList(new List<SObject>{ new Account(), new Contact() })
        );

        List<Contact> newContacts = new List<Contact>();

        for (Map.Entry<String, List<String>> entry : contactLastNamesByAccountName.entrySet()) {
            Account acc = new Account(Name = entry.getKey());
            uow.registerNewObject(acc);
            newAccounts.add(acc);

            List<String> lastNames = entry.getValue();
            if (lastNames != null) {
                for (String lastName : lastNames) {
                    // Set the sObject reference so the UoW can resolve AccountId after insert
                    Contact con = new Contact(LastName = lastName, Account = acc);
                    uow.registerNewObject(con);
                    newContacts.add(con);
                }
            }
        }

        // Tell the UoW: after each Account is inserted, set the matching Contact's AccountId.
        // Matching is driven by the sObject reference we set above (Contact.Account = acc).
        if (!newAccounts.isEmpty() && !newContacts.isEmpty()) {
            uow.registerRelationship(
                new SObject_TypeList(newAccounts),
                new SObject_TypeList(newContacts),
                'AccountId'
            );
        }

        uow.commitWork();

        return newAccounts;
    }
}
