    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Load via selector
        List<Opportunity> opps = OpportunitiesSelector.newInstance().selectById(opportunityIds);

        // Filter to only those not already Closed Won
        List<Opportunity> toUpdate = new List<Opportunity>();
        for (Opportunity opp : opps) {
            if (opp.StageName != 'Closed Won') {
                toUpdate.add(opp);
            }
        }

        if (toUpdate.isEmpty()) {
            return 0;
        }

        // Apply the change
        Date today = Date.today();
        for (Opportunity opp : toUpdate) {
            opp.StageName = 'Closed Won';
            opp.CloseDate = today;
        }

        // Single unit of work: register dirty rows + register platform-event publishes.
        // fflib commits DML first; only on success are the events published.
        // If commit throws, no events are published and the exception propagates.
        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        for (Opportunity opp : toUpdate) {
            uow.registerDirty(opp);

            Deal_Won__e evt = new Deal_Won__e();
            evt.Opportunity_Id__c = opp.Id;
            evt.Amount__c = opp.Amount;
            uow.registerPublish(evt);
        }

        uow.commit();

        return toUpdate.size();
    }
}
