public class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failures = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return failures;
        }

        // Defensive guards: ignore null IDs and avoid duplicate record processing.
        Set<Id> contactIdSet = new Set<Id>();
        for (Id contactId : contactIds) {
            if (contactId != null) {
                contactIdSet.add(contactId);
            }
        }

        if (contactIdSet.isEmpty()) {
            return failures;
        }

        List<Contact> contacts = new List<Contact>();

        for (Contact c : [SELECT Id, Phone FROM Contact WHERE Id IN :contactIdSet]) {
            if (String.isNotBlank(c.Phone)) {
                c.Phone = c.Phone.replaceAll('[^0-9+]', '');
                contacts.add(c);
            }
        }

        if (!contacts.isEmpty()) {
            Database.SaveResult[] results = Database.update(contacts, false);

            for (Database.SaveResult result : results) {
                if (!result.isSuccess()) {
                    if (result.getErrors().isEmpty()) {
                        failures.put(result.getId(), 'Unknown error');
                    } else {
                        failures.put(result.getId(), result.getErrors().get(0).getMessage());
                    }
                }
            }
        }

        return failures;
    }
}
