        // 2. Single bulk-safe SOQL — works for 1 case or 200 without hitting the query limit
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Rating FROM Account WHERE Id = :accountIds]
        );

        // 3. Loop through new cases and set Priority where appropriate
        for (Case c : newCases) {
            if (c.AccountId != null) {
                Account acc = accountsById.get(c.AccountId);
                if (acc != null && acc.Rating == 'Hot') {
                    c.Priority = 'High';
                }
            }
            // Cases without an account, or whose account isn't 'Hot',
            // keep the Priority they were inserted with (no change needed).
        }
    }
}
