public with sharing class LeadContactMatcher {
    // A map is preferable to nested loops here: it normalizes each email once and keeps
    // matching linear. First-contact ordering is preserved by inserting each email only once.
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> result = new List<Id>();
        if (leads == null) {
            return result;
        }

        Map<String, Contact> firstContactByEmail = new Map<String, Contact>();

        if (contacts != null) {
            for (Contact contact : contacts) {
                if (contact == null) {
                    continue;
                }

                String emailKey = normalizeEmail(contact.Email);
                if (emailKey != null && !firstContactByEmail.containsKey(emailKey)) {
                    firstContactByEmail.put(emailKey, contact);
                }
            }
        }

        for (Lead lead : leads) {
            String emailKey = (lead == null) ? null : normalizeEmail(lead.Email);
            Contact match = (emailKey == null) ? null : firstContactByEmail.get(emailKey);
            result.add((match == null) ? null : match.Id);
        }

        return result;
    }

    private static String normalizeEmail(String email) {
        if (email == null) {
            return null;
        }

        String normalized = email.trim();
        if (normalized.isEmpty()) {
            return null;
        }

        return normalized.toLowerCase();
    }
}
