```apex
/**
 * Handler for AccountTrigger (after update).
 *
 * When an account's BillingCountry changes, update MailingCountry on its contacts
 * only if the contact's MailingCountry is blank or was previously equal to the
 * account's old BillingCountry.
 *
 * Bulk-safe: one filtered SOQL, no queries in loops.
 */
public without sharing class AccountCountrySync {

    /**
     * Entry point called from the trigger.
     *
     * @param newAccounts   trigger.new
     * @param oldAccountMap trigger.oldMap
     */
    public static void handleAfterUpdate(List<Account> newAccounts, Map<Id, Account> oldAccountMap) {
        // --- Identify accounts whose BillingCountry actually changed -------------
        // Maps keyed by AccountId holding the new and old BillingCountry values.
        Map<Id, String> newCountryByAccount = new Map<Id, String>();
        Map<Id, String> oldCountryByAccount = new Map<Id, String>();

        for (Account acc : newAccounts) {
            String newBilling = acc.BillingCountry;
            String oldBilling = oldAccountMap.get(acc.Id).BillingCountry;

            if (newBilling != oldBilling) {
                newCountryByAccount.put(acc.Id, newBilling);
                oldCountryByAccount.put(acc.Id, oldBilling);
            }
        }

        // Nothing to do if no BillingCountry changed.
        if (newCountryByAccount.isEmpty()) {
            return;
        }

        // --- Single filtered SOQL (no query inside a loop) -----------------------
        // Loads only contacts belonging to the changed accounts (≤ ~10 k rows for
        // a 200-account batch), avoiding the 50k-row / 6MB-heap governor limits
        // that an unfiltered [SELECT ... FROM Contact] would hit at 2.3M records.
        List<Contact> contacts = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :newCountryByAccount.keySet()
        ];

        // --- Determine which contacts need updating ------------------------------
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact c : contacts) {
            String newCountry = newCountryByAccount.get(c.AccountId);
            String oldCountry = oldCountryByAccount.get(c.AccountId);

            // Condition: blank MailingCountry OR equals the account's previous BillingCountry
            Boolean isBlank      = String.isBlank(c.MailingCountry);
            Boolean matchesOld   = (oldCountry != null && c.MailingCountry == oldCountry);

            if (isBlank || matchesOld) {
                c.MailingCountry = newCountry;
                contactsToUpdate.add(c);
            }
        }

        // --- Persist changes -----------------------------------------------------
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
```

### How the logic satisfies every requirement

| Requirement | How it's met |
|---|---|
| Only fires on `BillingCountry` *change* | Compares `trigger.new` vs `trigger.oldMap` before adding to the maps. |
| Blank `MailingCountry` → update | `String.isBlank(c.MailingCountry)` catches `null` and `""`. |
| `MailingCountry == old BillingCountry` → update | Equality check against `oldCountryByAccount`. |
| Contacts working abroad (different country) | Neither condition is true → contact is left out of `contactsToUpdate`. |
| Contacts of unchanged accounts | Those AccountIds are absent from `newCountryByAccount`; their contacts won't match any row in the filtered query. |
| One SOQL, no queries in loops | A single `SELECT … WHERE AccountId IN :keySet()` above the inner loop. |
| 200-account / 2.3M-contact scale | Filtered query returns only contacts for ≤ 200 accounts (~10k rows), well within the 50k-row and 6MB heap limits. |

