```js
import { LightningElement, track } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY_MS = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    @track contacts = [];
    @track errorMessage = null;

    debounceTimer = null;
    requestId = 0;
    isDisconnected = false;

    get hasResults() {
        return Array.isArray(this.contacts) && this.contacts.length > 0;
    }

    connectedCallback() {
        this.isDisconnected = false;
        this.clearDebounceTimer();
    }

    disconnectedCallback() {
        this.isDisconnected = true;
        this.clearDebounceTimer();
        this.requestId += 1;
    }

    handleChange(event) {
        if (this.isDisconnected) {
            return;
        }

        this.clearDebounceTimer();

        // Any previous pending debounce or in-flight response is no longer
        // tied to the latest user input.
        this.requestId += 1;
        this.errorMessage = null;

        const targetValue = event && event.target ? event.target.value : undefined;
        const detailValue = event && event.detail ? event.detail.value : undefined;
        const rawValue = targetValue !== undefined ? targetValue : detailValue;
        const searchTerm = (rawValue === null || rawValue === undefined ? '' : String(rawValue)).trim();

        if (searchTerm.length < MIN_SEARCH_LENGTH) {
            this.contacts = [];
            return;
        }

        const pendingSearchTerm = searchTerm;

        this.debounceTimer = setTimeout(() => {
            this.debounceTimer = null;

            if (this.isDisconnected) {
                return;
            }

            this.runSearch(pendingSearchTerm, this.requestId);
        }, DEBOUNCE_DELAY_MS);
    }

    runSearch(searchTerm, requestId) {
        if (this.isDisconnected) {
            return;
        }

        searchContacts({ searchTerm })
            .then((result) => {
                if (this.isDisconnected || requestId !== this.requestId) {
                    return;
                }

                this.contacts = Array.isArray(result) ? result : [];
                this.errorMessage = null;
            })
            .catch((error) => {
                if (this.isDisconnected || requestId !== this.requestId) {
                    return;
                }

                this.contacts = [];
                this.errorMessage = this.getErrorMessage(error);
            });
    }

    clearDebounceTimer() {
        if (this.debounceTimer !== null && this.debounceTimer !== undefined) {
            clearTimeout(this.debounceTimer);
            this.debounceTimer = null;
        }
    }

    getErrorMessage(error) {
        if (error && error.body && error.body.message) {
            return error.body.message;
        }
        if (error && error.message) {
            return error.message;
        }
        if (typeof error === 'string') {
            return error;
        }

        return 'Search failed.';
    }
}
