import { LightningElement } from 'lwc';
import register from '@salesforce/apex/RegistrationController.register';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const PERSONAL_EMAIL_DOMAINS = new Set([
    'gmail.com',
    'yahoo.com',
    'hotmail.com',
    'outlook.com'
]);

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleFullNameChange(event) {
        this.fullName = this.getValueFromChange(event);
    }

    handleEmailChange(event) {
        this.email = this.getValueFromChange(event);
    }

    handleCompanyChange(event) {
        this.company = this.getValueFromChange(event);
    }

    async handleRegister(event) {
        event?.preventDefault();

        const emailInput = this.template.querySelector('lightning-input[data-field="email"]');
        if (emailInput && typeof emailInput.setCustomValidity === 'function') {
            const domain = this.getEmailDomain(this.email);

            if (PERSONAL_EMAIL_DOMAINS.has(domain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        const inputs = Array.from(this.template.querySelectorAll('lightning-input'));
        let hasErrors = false;

        inputs.forEach((input) => {
            if (!input.reportValidity()) {
                hasErrors = true;
            }
        });

        if (hasErrors) {
            return;
        }

        const fullName = this.fullName ?? '';
        const email = this.email ?? '';
        const company = this.company ?? '';

        try {
            await register({ fullName, email, company });

            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    variant: 'success'
                })
            );
        } catch (error) {
            const message = error && error.body ? error.body.message : (error ? error.message || String(error) : '');

            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    variant: 'error',
                    message
                })
            );
        }
    }

    getValueFromChange(event) {
        const detailValue = event?.detail?.value;
        const targetValue = event?.target?.value;
        const value = detailValue === undefined ? targetValue : detailValue;
        return value === undefined || value === null ? '' : value;
    }

    getEmailDomain(email) {
        const normalizedEmail = String(email ?? '').trim().toLowerCase();

        if (!normalizedEmail.includes('@')) {
            return '';
        }

        const parts = normalizedEmail.split('@');
        return parts[parts.length - 1].trim();
    }
}
