/**
 * EmployerService – manages NPSP Current/Primary affiliations
 * for donor contacts whose employer arrives via a web form.
 *
 * Relies on NPSP's Affiliation trigger/handler so that a previously-
 * primary Current affiliation is automatically flipped to Former
 * (end date = today) when a new Current + Primary one is inserted.
 */
public with sharing class EmployerService {

    /**
     * @param employerByContactId  ContactId → Organization AccountId
     *                             A null or empty map is a no-op.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        // Guard: nothing to do
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // ── SOQL 1 ──────────────────────────────────────────────────────
        // Fetch each contact's *current* primary affiliation (if any).
        // This lets us skip contacts that already point to the target org
        // (idempotency / no duplicate affiliation requirement).
        Map<Id, Id> currentPrimaryOrgByContact = new Map<Id, Id>();
        for (npe5__Affiliation__c aff : [
            SELECT npe5__Contact__c, npe5__Organization__c
            FROM   npe5__Affiliation__c
            WHERE  npe5__Contact__c  IN :contactIds
              AND  npe5__Status__c   = 'Current'
              AND  npe5__Primary__c  = true
        ]) {
            currentPrimaryOrgByContact.put(
                aff.npe5__Contact__c,
                aff.npe5__Organization__c
            );
        }

        // ── Build records that need changes ─────────────────────────────
        List<npe5__Affiliation__c> newAffiliations   = new List<npe5__Affiliation__c>();
        List<Contact>              contactsToUpdate = new List<Contact>();

        for (Id contactId : contactIds) {
            Id targetOrgId = employerByContactId.get(contactId);

            // Already Current + Primary to this org → nothing to do
            if (currentPrimaryOrgByContact.get(contactId) == targetOrgId) {
                continue;
            }

            // New affiliation – NPSP trigger will retire the old one (Former,
            // end-date = today) and refresh Contact.npsp__Primary_Affiliation__c.
            newAffiliations.add(new npe5__Affiliation__c(
                npe5__Contact__c     = contactId,
                npe5__Organization__c= targetOrgId,
                npe5__Status__c      = 'Current',
                npe5__Primary__c     = true
            ));

            // Belt-and-suspenders: explicitly ensure the contact lookup
            // is correct even if a future NPSP release changes trigger
            // behaviour.  A partial-record update touches only the one field.
            contactsToUpdate.add(new Contact(
                Id                            = contactId,
                npsp__Primary_Affiliation__c  = targetOrgId
            ));
        }

        // ── DML 1 – insert new affiliations ─────────────────────────────
        // NPSP's Affiliation handler fires synchronously here, converting the
        // previous Current+Primary record to Former (npe5__EndDate__c = today)
        // and updating Contact.npsp__Primary_Affiliation__c.
        if (!newAffiliations.isEmpty()) {
            insert newAffiliations;
        }

        // ── DML 2 – confirm the contact lookup ──────────────────────────
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
```

**How it satisfies every requirement**

| Requirement | How |
|---|---|
| Null / empty map → no-op | Early-return guard |
| Current + Primary affiliation exists | `npe5__Status__c='Current'`, `npe5__Primary__c=true` on insert |
| `Contact.npsp__Primary_Affiliation__c` → org | NPSP's Affiliation trigger sets it on insert; DML 2 re-confirms |
| Old employer → Former, non-primary, end-date today | NPSP's standard Affiliation handler does this automatically when a new Primary is inserted |
| Contact stays in household | We never touch `Contact.AccountId`; partial-record updates only set the lookup field |
| No duplicate if org is already primary | `currentPrimaryOrgByContact` check skips those contacts entirely |
| ≤ 2 SOQL | **1** query (existing Current+Primary affiliations) |
| ≤ 2 DML of its own | **1** insert + **1** update |
| 200 contacts in one call | All filtering/building is in memory; queries/DMLs are bulk-safe |

