public class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        // ── Validation (all before any DML) ──────────────────────────────
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException(
                'The percent-by-GAU map must not be null or empty.'
            );
        }

        Decimal totalPercent = 0;
        Set<Id> gauIdSet = new Set<Id>();

        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);

            if (pct == null) {
                throw new AllocationException(
                    'A percentage value must not be null.'
                );
            }
            if (pct <= 0) {
                throw new AllocationException(
                    'Every percentage must be greater than 0.'
                );
            }

            totalPercent += pct;
            gauIdSet.add(gauId);
        }

        if (totalPercent > 100) {
            throw new AllocationException(
                'Percentages must not sum to more than 100.'
            );
        }

        // ── Validate GAUs exist and are active ───────────────────────────
        List<npsp__General_Accounting_Unit__c> gaus = [
            SELECT Id, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :gauIdSet
        ];

        if (gaus.size() != gauIdSet.size()) {
            throw new AllocationException(
                'One or more GAU Ids do not correspond to existing records.'
            );
        }

        for (npsp__General_Accounting_Unit__c gau : gaus) {
            if (!gau.npsp__Active__c) {
                throw new AllocationException(
                    'GAU ' + gau.Id + ' is inactive.'
                );
            }
        }

        // ── Replace existing allocations for this opportunity ────────────
        List<npsp__Allocation__c> existing = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        if (!existing.isEmpty()) {
            delete existing;
        }

        // ── Build percent-based allocations ──────────────────────────────
        //    Setting only npsp__Percent__c (leaving npsp__Amount__c null)
        //    ensures NPSP recalculates amounts whenever the opportunity
        //    amount changes later – e.g. 60/40 on $1 000 becomes
        //    $1 200/$800 when corrected to $2 000.
        List<npsp__Allocation__c> allocations =
            new List<npsp__Allocation__c>();

        for (Id gauId : percentByGauId.keySet()) {
            npsp__Allocation__c alloc = new npsp__Allocation__c();
            alloc.npsp__Opportunity__c            = opportunityId;
            alloc.npsp__General_Accounting_Unit__c = gauId;
            alloc.npsp__Percent__c                = percentByGauId.get(gauId);
            // npsp__Amount__c intentionally left null  → percent-based
            // npsp__Payment__c intentionally left null → NPSP links to
            //     the opportunity's default payment automatically

            allocations.add(alloc);
        }

        insert allocations;

        return allocations;
    }
}
