public class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        // Validate amount
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Gift amount must be greater than zero.');
        }

        // Validate contact exists and retrieve needed fields
        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];

        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist.');
        }
        Contact primaryContact = contacts[0];

        // Retrieve all household members via the contact's account
        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :primaryContact.AccountId
        ];

        // Build the opportunity name: "<FirstName> <LastName> Donation <yyyy-MM-dd>"
        String dateStr = String.valueOf(giftDate.year()) + '-' +
                         String.valueOf(giftDate.month()).leftPad(2, '0') + '-' +
                         String.valueOf(giftDate.day()).leftPad(2, '0');
        String oppName = primaryContact.FirstName + ' ' + primaryContact.LastName + ' Donation ' + dateStr;

        // Create the Closed Won Opportunity
        Opportunity opp = new Opportunity(
            Name                    = oppName,
            AccountId               = primaryContact.AccountId,
            Amount                  = amount,
            CloseDate               = giftDate,
            StageName               = 'Closed Won',
            npsp__Primary_Contact__c = primaryContact.Id
        );
        insert opp;

        // Create contact roles: primary contact = "Donor", others = "Household Member"
        List<OpportunityContactRole> roles = new List<OpportunityContactRole>();
        for (Contact member : householdMembers) {
            Boolean isPrimary = (member.Id == primaryContact.Id);
            OpportunityContactRole ocr = new OpportunityContactRole(
                OpportunityId = opp.Id,
                ContactId     = member.Id,
                Role          = isPrimary ? 'Donor' : 'Household Member',
                IsPrimary     = isPrimary
            );
            roles.add(ocr);
        }
        if (!roles.isEmpty()) {
            insert roles;
        }

        // Create exactly one paid payment for the full amount
        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c  = opp.Id,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c   = giftDate,
            npe01__Scheduled_Date__c = giftDate,
            npe01__Paid__c           = true
        );
        insert payment;

        return opp.Id;
    }
}
