/**
 * Service for importing contacts from a legacy system.
 * Inserts contacts with phone formatting automation intact,
 * while selectively skipping only the welcome-task action via
 * the Trigger Actions Framework bypass API.
 */
public class ContactImportService {

    private static final String ACTION_CREATE_WELCOME_TASK = 'TA_Contact_CreateWelcomeTask';

    /**
     * Insert the supplied contacts in a single DML statement.
     * TA_Contact_CreateWelcomeTask is bypassed for this insert only;
     * all other registered Contact actions (e.g. TA_Contact_FormatPhone)
     * execute normally.  The bypass is guaranteed to be cleared before the
     * method returns, regardless of whether the DML succeeds or throws.
     */
    public static void importContacts(List<Contact> contacts) {
        // Nothing to do for a null or empty list – avoids "Insufficient ID count" DML error.
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Bypass only the specific after-insert action; before-insert formatting
        // and any other Contact automation remain active.
        MetadataTriggerHandler.bypass(ACTION_CREATE_WELCOME_TASK);
        try {
            insert contacts;
        } finally {
            // Ensure the bypass never leaks beyond this method.
            MetadataTriggerHandler.clearBypass(ACTION_CREATE_WELCOME_TASK);
        }
    }
}
