```apex
public class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MSG =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> contacts = (List<Contact>) triggerNew;
        if (contacts.isEmpty()) return;

        // Identify within-save duplicates; only the first occurrence per key is a candidate.
        Map<String, Integer> firstSeen = new Map<String, Integer>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emailsLower = new Set<String>();
        Set<Integer> rejectedBySave = new Set<Integer>();

        for (Integer i = 0; i < contacts.size(); i++) {
            Contact c = contacts[i];
            if (c.AccountId == null || String.isBlank(c.Email)) continue;

            String key = c.AccountId + '|' + c.Email.toLowerCase();
            if (firstSeen.containsKey(key)) {
                c.addError(ERROR_MSG);
                rejectedBySave.add(i);
            } else {
                firstSeen.put(key, i);
                accountIds.add(c.AccountId);
                emailsLower.add(c.Email.toLowerCase());
            }
        }

        // Single SOQL query against the database for pre-existing duplicates.
        if (!accountIds.isEmpty()) {
            Map<String, Set<Id>> dbKeyToIds = buildDbKeyToIds(accountIds, emailsLower);

            for (Integer i = 0; i < contacts.size(); i++) {
                if (rejectedBySave.contains(i)) continue;
                Contact c = contacts[i];
                if (c.AccountId == null || String.isBlank(c.Email)) continue;

                String key = c.AccountId + '|' + c.Email.toLowerCase();
                Set<Id> dbIds = dbKeyToIds.get(key);
                if (dbIds != null && !dbIds.isEmpty()) {
                    c.addError(ERROR_MSG);
                }
            }
        }
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        List<Contact> oldContacts = (List<Contact>) triggerOld;
        if (newContacts.isEmpty()) return;

        // Only contacts whose Email or AccountId changed are candidates.
        Map<String, Integer> firstSeen = new Map<String, Integer>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emailsLower = new Set<String>();
        Set<Integer> rejectedBySave = new Set<Integer>();
        Set<Integer> candidatesForDbCheck = new Set<Integer>();

        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact nc = newContacts[i];
            Contact oc = oldContacts[i];

            // Skip if neither Email nor AccountId changed.
            if (nc.AccountId == oc.AccountId && nc.Email == oc.Email) continue;
            // Skip if missing Account or Email.
            if (nc.AccountId == null || String.isBlank(nc.Email)) continue;

            String key = nc.AccountId + '|' + nc.Email.toLowerCase();
            if (firstSeen.containsKey(key)) {
                nc.addError(ERROR_MSG);
                rejectedBySave.add(i);
            } else {
                firstSeen.put(key, i);
                candidatesForDbCheck.add(i);
                accountIds.add(nc.AccountId);
                emailsLower.add(nc.Email.toLowerCase());
            }
        }

        // Single SOQL query; exclude self from conflicts.
        if (!accountIds.isEmpty()) {
            Map<String, Set<Id>> dbKeyToIds = buildDbKeyToIds(accountIds, emailsLower);

            for (Integer i : candidatesForDbCheck) {
                if (rejectedBySave.contains(i)) continue;
                Contact nc = newContacts[i];

                String key = nc.AccountId + '|' + nc.Email.toLowerCase();
                Set<Id> dbIds = dbKeyToIds.get(key);
                if (dbIds != null) {
                    dbIds.remove(nc.Id); // never conflicts with itself
                    if (!dbIds.isEmpty()) {
                        nc.addError(ERROR_MSG);
                    }
                }
            }
        }
    }

    private Map<String, Set<Id>> buildDbKeyToIds(Set<Id> accountIds, Set<String> emailsLower) {
        Map<String, Set<Id>> result = new Map<String, Set<Id>>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email IN :emailsLower
        ]) {
            String key = existing.AccountId + '|' + existing.Email.toLowerCase();
            if (!result.containsKey(key)) {
                result.put(key, new Set<Id>());
            }
            result.get(key).add(existing.Id);
        }
        return result;
    }
}
