trigger OpportunityTrigger on Opportunity (
    before insert, before update, before delete,
    after insert, after update, after delete, after undelete
) {
    if (Trigger.isBefore) {
        if (Trigger.isInsert) {
            new MetadataTriggerHandler().beforeInsert(Trigger.new);
        } else if (Trigger.isUpdate) {
            new MetadataTriggerHandler().beforeUpdate(Trigger.new, Trigger.old);
        } else if (Trigger.isDelete) {
            new MetadataTriggerHandler().beforeDelete(Trigger.old);
        }
    } else {
        if (Trigger.isInsert) {
            new MetadataTriggerHandler().afterInsert(Trigger.new);
        } else if (Trigger.isUpdate) {
            new MetadataTriggerHandler().afterUpdate(Trigger.new, Trigger.old);
        } else if (Trigger.isDelete) {
            new MetadataTriggerHandler().afterDelete(Trigger.old);
        } else if (Trigger.isUndelete) {
            new MetadataTriggerHandler().afterUndelete(Trigger.new);
        }
    }
}
