public with sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        for (SObject s : triggerNew) {
            Lead lead = (Lead) s;

            // Email: remove leading/trailing whitespace and lowercase; null stays null
            if (lead.Email != null) {
                lead.Email = lead.Email.trim().toLowerCase();
            }

            // Company: remove leading/trailing whitespace
            if (lead.Company != null) {
                lead.Company = lead.Company.trim();
            }

            // LeadSource: default to "Web" when blank; keep existing value
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }
        }
    }
}
